173	func renderDotChart(w io.Writer, sty activityStyles, hourly []hourlyPoint, repos []repoContribution) {
174		agentTotals := make(map[string]int)
175		total := 0
176		for _, r := range repos {
177			total += r.Total
178			for agent, count := range r.Agents {
179				agentTotals[agent] += count
180			}
181		}
182	
183		totalLabel := ""
184		if total > 0 {
185			totalLabel = sty.render(sty.muted, fmt.Sprintf("  %d checkpoints", total))
186		}
187		fmt.Fprintf(w, "%s%s\n", sty.render(sty.label, "CONTRIBUTIONS"), totalLabel)
188	
189		if len(hourly) == 0 {
190			fmt.Fprintln(w, sty.render(sty.muted, "  No activity data"))
191			return
192		}
193	
194		now := time.Now().Local()
195		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
196		numDays := 30
197	
198		// 4 hour bands: 0-5, 6-11, 12-17, 18-23
199		type hourBand struct {
200			label  string
201			lo, hi int
202		}
203		bands := []hourBand{
204			{" 0", 0, 5},
205			{" 6", 6, 11},
206			{"12", 12, 17},
207			{"18", 18, 23},
208		}
209	
210		// Grid: [band][day] -> best point
211		type cell struct {
212			value   int
213			agentID string
214		}
215		grid := make([][]cell, len(bands))
216		for i := range grid {
217			grid[i] = make([]cell, numDays)
218		}
219	
220		for _, p := range hourly {
221			pt, err := time.ParseInLocation("2006-01-02", p.Date, time.Local)
222			if err != nil {
223				continue
224			}
225			dayIdx := int(today.Sub(pt).Hours() / 24)
226			col := numDays - 1 - dayIdx
227			if col < 0 || col >= numDays {
228				continue
229			}
230			band := -1
231			for i, hb := range bands {
232				if p.Hour >= hb.lo && p.Hour <= hb.hi {
233					band = i
234					break
235				}
236			}
237			if band < 0 {
238				continue
239			}
240			if p.Value > grid[band][col].value {
241				grid[band][col] = cell{value: p.Value, agentID: p.AgentID}
242			}
243		}
244	
245		sizeChars := []string{" ", "·", "•", "●", "⬤"}
246		sizeFor := func(v int) int {
247			switch {
248			case v == 0:
249				return 0
250			case v <= 2:
251				return 1
252			case v <= 5:
253				return 2
254			case v <= 9:
255				return 3
256			default:
257				return 4
258			}
259		}
260	
261		labelWidth := 3
262		availCols := sty.width - labelWidth - 2
263		colWidth := availCols / numDays
264		if colWidth < 1 {
265			colWidth = 1
266		}
267	
268		// Date axis
269		fmt.Fprint(w, strings.Repeat(" ", labelWidth+1))
270		startDate := today.AddDate(0, 0, -(numDays - 1))
271		lastMonth := ""
272		for d := 0; d < numDays; d++ {
273			date := startDate.AddDate(0, 0, d)
274			month := date.Format("Jan")
275			if month != lastMonth {
276				fmt.Fprint(w, sty.render(sty.muted, month))
277				labelCols := int(math.Ceil(float64(len(month)) / float64(max(colWidth, 1))))
278				if labelCols < 1 {
279					labelCols = 1
280				}
281				d += labelCols - 1
282				lastMonth = month
283			} else {
284				fmt.Fprint(w, strings.Repeat(" ", colWidth))
285			}
286		}
287		fmt.Fprintln(w)
288	
289		// Grid rows
290		for band, hb := range bands {
291			fmt.Fprint(w, sty.render(sty.dim, hb.label)+" ")
292			for col := range numDays {
293				c := grid[band][col]
294				sz := sizeFor(c.value)
295				if sz == 0 {
296					fmt.Fprint(w, strings.Repeat(" ", colWidth))
297				} else {
298					fmt.Fprint(w, sty.renderAgent(c.agentID, sizeChars[sz])+strings.Repeat(" ", colWidth-1))
299				}
300			}
301			fmt.Fprintln(w)
302		}
303	
304		// Size legend
305		fmt.Fprintln(w, sty.render(sty.dim, "     · 1-2   • 3-5   ● 6-9   ⬤ 10+"))
306	
307		// Agent legend
308		if total > 0 {
309			var parts []string
310			for _, id := range agentOrder {
311				count, ok := agentTotals[id]
312				if !ok || count == 0 {
313					continue
314				}
315				pct := float64(count) / float64(total) * 100
316				display := agentDisplayMap[id]
317				parts = append(parts, sty.renderAgent(id, fmt.Sprintf("● %s %d%%", display.Label, int(math.Round(pct)))))
318			}
319			fmt.Fprintln(w, strings.Join(parts, sty.render(sty.dim, "  ")))
320		}
321	}
