369	func renderAgentBar(sty activityStyles, agents map[string]int, maxCount, barWidth int) string {
370		if maxCount == 0 {
371			return strings.Repeat(" ", barWidth)
372		}
373	
374		var b strings.Builder
375	
376		filled := 0
377		for _, id := range agentOrder {
378			count, ok := agents[id]
379			if !ok || count == 0 {
380				continue
381			}
382			segWidth := int(math.Round(float64(count) / float64(maxCount) * float64(barWidth)))
383			if segWidth < 1 && count > 0 {
384				segWidth = 1
385			}
386			if filled+segWidth > barWidth {
387				segWidth = barWidth - filled
388			}
389			if segWidth <= 0 {
390				continue
391			}
392	
393			display := agentDisplayMap[id]
394			seg := strings.Repeat(string(display.Char), segWidth)
395			b.WriteString(sty.renderAgent(id, seg))
396			filled += segWidth
397		}
398	
399		if filled < barWidth {
400			b.WriteString(sty.render(sty.dim, strings.Repeat("░", barWidth-filled)))
401		}
402	
403		return b.String()
404	}
