410	func renderCommitListN(w io.Writer, sty activityStyles, days []commitDay, maxDays int) {
411		if len(days) == 0 {
412			return
413		}
414	
415		if maxDays <= 0 || maxDays > len(days) {
416			maxDays = len(days)
417		}
418	
419		for _, day := range days[:maxDays] {
420			displayDate := formatCommitDate(day.Date)
421			commitWord := "commits"
422			if len(day.Commits) == 1 {
423				commitWord = "commit"
424			}
425	
426			fmt.Fprintf(w, "%s  %s\n",
427				sty.render(sty.bold, displayDate),
428				sty.render(sty.muted, fmt.Sprintf("%d %s", len(day.Commits), commitWord)))
429	
430			for _, c := range day.Commits {
431				sha := c.CommitSHA
432				if len(sha) > 7 {
433					sha = sha[:7]
434				}
435	
436				msg := "(no message)"
437				if c.CommitMsg != nil && *c.CommitMsg != "" {
438					msg = firstLine(*c.CommitMsg)
439				}
440	
441				var badges []string
442				for _, a := range uniqueCommitAgents(c) {
443					display := agentDisplayMap[a]
444					badges = append(badges, sty.renderAgent(a, display.Label))
445				}
446	
447				fileStats := fmt.Sprintf("%d files", c.FilesChanged)
448				if c.FilesChanged == 1 {
449					fileStats = "1 file"
450				}
451	
452				cpCount := len(c.Checkpoints)
453				cpStr := ""
454				if cpCount == 1 {
455					cpStr = "1 checkpoint"
456				} else if cpCount > 1 {
457					cpStr = fmt.Sprintf("%d checkpoints", cpCount)
458				}
459	
460				// Build right-aligned stats: +N / -N  M files  [K checkpoints]
461				var statParts []string
462				statParts = append(statParts,
463					sty.render(sty.add, fmt.Sprintf("+%d", c.Additions))+
464						sty.render(sty.muted, " / ")+
465						sty.render(sty.del, fmt.Sprintf("-%d", c.Deletions)))
466				statParts = append(statParts, sty.render(sty.muted, fileStats))
467				if cpStr != "" {
468					statParts = append(statParts, sty.render(sty.muted, cpStr))
469				}
470				rightSide := strings.Join(statParts, sty.render(sty.dim, "  "))
471				// Plain length for padding (ANSI codes don't count)
472				rightPlain := fmt.Sprintf("+%d / -%d  %s", c.Additions, c.Deletions, fileStats)
473				if cpStr != "" {
474					rightPlain += "  " + cpStr
475				}
476	
477				// Build left side: hash  message  repo  [badges]
478				left := sty.render(sty.commitH, sha) + " " +
479					sty.render(sty.commitM, msg) + " " +
480					sty.render(sty.muted, c.RepoFullName)
481				leftPlain := sha + " " + msg + " " + c.RepoFullName
482				var leftSb359 strings.Builder
483				for _, badge := range badges {
484					leftSb359.WriteString("  " + badge)
485				}
486				left += leftSb359.String()
487				var leftPlainSb362 strings.Builder
488				for _, a := range uniqueCommitAgents(c) {
489					leftPlainSb362.WriteString("  " + agentDisplayMap[a].Label)
490				}
491				leftPlain += leftPlainSb362.String()
492	
493				// Truncate message if line would exceed width
494				maxMsg := sty.width - (lipgloss.Width(leftPlain) - lipgloss.Width(msg)) - lipgloss.Width(rightPlain) - 2
495				if maxMsg < 10 {
496					maxMsg = 10
497				}
498				if lipgloss.Width(msg) > maxMsg {
499					msg = truncateDisplayWidth(msg, maxMsg, "...")
500					// Rebuild left side with truncated message
501					left = sty.render(sty.commitH, sha) + " " +
502						sty.render(sty.commitM, msg) + " " +
503						sty.render(sty.muted, c.RepoFullName)
504					leftPlain = sha + " " + msg + " " + c.RepoFullName
505					var leftSb378 strings.Builder
506					for _, badge := range badges {
507						leftSb378.WriteString("  " + badge)
508					}
509					left += leftSb378.String()
510					var leftPlainSb381 strings.Builder
511					for _, a := range uniqueCommitAgents(c) {
512						leftPlainSb381.WriteString("  " + agentDisplayMap[a].Label)
513					}
514					leftPlain += leftPlainSb381.String()
515				}
516	
517				gap := sty.width - lipgloss.Width(leftPlain) - lipgloss.Width(rightPlain)
518				if gap < 2 {
519					gap = 2
520				}
521				fmt.Fprintf(w, "%s%s%s\n", left, strings.Repeat(" ", gap), rightSide)
522			}
523			fmt.Fprintln(w)
524		}
525	}
