527	func uniqueCommitAgents(c userCommit) []string {
528		seen := make(map[string]struct{})
529		var result []string
530		for _, cp := range c.Checkpoints {
531			agents := cp.Agents
532			// Fall back to singular Agent field when Agents slice is empty
533			if len(agents) == 0 && cp.Agent != "" {
534				agents = []string{cp.Agent}
535			}
536			for _, a := range agents {
537				id := normalizeAgentString(a)
538				if _, ok := seen[id]; !ok {
539					seen[id] = struct{}{}
540					result = append(result, id)
541				}
542			}
543		}
544		sort.Strings(result)
545		return result
546	}
