548	func formatCommitDate(dateStr string) string {
549		t, err := time.ParseInLocation("2006-01-02", dateStr, time.Local)
550		if err != nil {
551			return dateStr
552		}
553		now := time.Now().Local()
554		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
555		days := int(today.Sub(t).Hours() / 24)
556	
557		switch days {
558		case 0:
559			return t.Format("Monday 2 Jan") + " (today)"
560		case 1:
561			return t.Format("Monday 2 Jan") + " (yesterday)"
562		default:
563			return t.Format("Monday 2 Jan")
564		}
565	}
