567	func padOrTruncate(s string, width int) string {
568		runes := []rune(s)
569		if len(runes) > width {
570			return string(runes[:width-1]) + "…"
571		}
572		return s + strings.Repeat(" ", width-len(runes))
573	}
574	
575	func truncateDisplayWidth(s string, width int, tail string) string {
576		if lipgloss.Width(s) <= width {
577			return s
578		}
579		if width <= 0 {
580			return ""
581		}
582		if lipgloss.Width(tail) >= width {
583			return tail[:width]
584		}
585	
586		var b strings.Builder
587		remaining := width - lipgloss.Width(tail)
588		for _, r := range s {
589			if lipgloss.Width(b.String()+string(r)) > remaining {
590				break
591			}
592			b.WriteRune(r)
593		}
594		return b.String() + tail
595	}
