98	func (m activityModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
99		switch msg := msg.(type) {
100		case activityDataMsg:
101			m.loading = false
102			m.stats = &msg.stats
103			m.repos = msg.repos
104			m.hourly = msg.hourly
105			m.days = msg.days
106			if m.width > 0 {
107				m = m.withViewport()
108			}
109			return m, nil
110	
111		case activityErrMsg:
112			m.loading = false
113			m.loadErr = msg.err
114			return m, nil
115	
116		case tea.KeyPressMsg:
117			if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
118				return m, tea.Quit
119			}
120			if key.Matches(msg, keys.Home) {
121				if m.ready {
122					m.viewport.GotoTop()
123				}
124				return m, nil
125			}
126			if key.Matches(msg, keys.End) {
127				if m.ready {
128					m.viewport.GotoBottom()
129				}
130				return m, nil
131			}
132	
133		case tea.WindowSizeMsg:
134			m.width = msg.Width
135			m.height = msg.Height
136			m.sty = newActivityStylesWithWidth(m.width, m.useColor)
137			if m.stats != nil {
138				m = m.withViewport()
139			}
140			return m, nil
141	
142		case spinner.TickMsg:
143			if m.loading {
144				var cmd tea.Cmd
145				m.spinner, cmd = m.spinner.Update(msg)
146				return m, cmd
147			}
148		}
149	
150		if m.ready {
151			var cmd tea.Cmd
152			m.viewport, cmd = m.viewport.Update(msg)
153			return m, cmd
154		}
155	
156		return m, nil
157	}
