227	func (m activityModel) renderFooter() string {
228		if !m.sty.colorEnabled {
229			return ""
230		}
231		helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
232		keyStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
233		sep := helpStyle.Render(" · ")
234	
235		fullHelp := keyStyle.Render("↑/↓, j/k") + helpStyle.Render(" scroll") +
236			sep + keyStyle.Render("home/end, g/G") + helpStyle.Render(" top/bottom") +
237			sep + keyStyle.Render(keys.Quit.Help().Key) + helpStyle.Render(" "+keys.Quit.Help().Desc)
238		standardHelp := keyStyle.Render("↑/↓") + helpStyle.Render(" scroll") +
239			sep + keyStyle.Render("home/end") + helpStyle.Render(" top/bottom") +
240			sep + keyStyle.Render(keys.Quit.Help().Key) + helpStyle.Render(" "+keys.Quit.Help().Desc)
241		shortHelp := keyStyle.Render("↑/↓") + helpStyle.Render(" scroll")
242		quitHelp := keyStyle.Render(keys.Quit.Help().Key) + helpStyle.Render(" "+keys.Quit.Help().Desc)
243		helpChoices := []string{fullHelp, standardHelp, shortHelp, quitHelp}
244	
245		if m.viewport.TotalLineCount() <= m.viewport.Height() {
246			for _, help := range helpChoices {
247				if m.width <= 0 || lipgloss.Width(help) <= m.width {
248					return help
249				}
250			}
251			return ""
252		}
253	
254		pct := helpStyle.Render(padLeft(int(m.viewport.ScrollPercent()*100)) + "%")
255		for _, help := range helpChoices {
256			gap := m.width - lipgloss.Width(help) - lipgloss.Width(sep) - lipgloss.Width(pct)
257			if gap >= 1 {
258				return help + sep + helpStyle.Render(strings.Repeat(" ", gap)) + pct
259			}
260		}
261	
262		pctWidth := lipgloss.Width(pct)
263		if m.width < pctWidth {
264			return helpStyle.Render(strings.Repeat(" ", max(m.width, 0)))
265		}
266		return helpStyle.Render(strings.Repeat(" ", m.width-pctWidth)) + pct
267	}
