155	// detectTimezone returns a best-effort timezone name for the current host.
156	// Order: $TZ → /etc/localtime symlink → time.Local → "UTC" as last resort.
157	// A candidate that fails normalization is skipped (not forwarded, not coerced
158	// to UTC), so a bogus $TZ on a correctly-configured box still yields the
159	// system timezone from /etc/localtime. The server is the canonical authority
160	// for what counts as a valid zone and falls back to UTC for anything it
161	// doesn't recognize, so we only do enough validation to avoid sending
162	// obvious garbage (paths, POSIX forms Go can't load, the "Local" sentinel).
163	func detectTimezone() string {
164		if tz := normalizeTimezone(os.Getenv("TZ")); tz != "" {
165			return tz
166		}
167		if link, err := os.Readlink("/etc/localtime"); err == nil {
168			if tz := normalizeTimezone(link); tz != "" {
169				return tz
170			}
171		}
172		if tz := normalizeTimezone(time.Local.String()); tz != "" {
173			return tz
174		}
175		return "UTC"
176	}
177	
178	// normalizeTimezone returns a name Go can load as a time zone, or "" if the
179	// input can't be resolved. It strips the POSIX ":" prefix and zoneinfo path
180	// prefix, then requires time.LoadLocation to succeed.
181	//
182	// This is not strict IANA-only validation: Go's LoadLocation accepts legacy
183	// aliases like EST5EDT, GMT0, and PST8PDT in addition to Area/Location
184	// names. Those may or may not be canonically understood by the server — if
185	// the server doesn't recognize one, it falls back to UTC on its end. We
186	// accept that mild mis-bucketing risk as the price of a simple check that
187	// catches the common failure modes (paths, unknown POSIX forms like UTC0,
188	// typos, the "Local" sentinel).
189	func normalizeTimezone(raw string) string {
190		name := strings.TrimPrefix(raw, ":")
191		const marker = "/zoneinfo/"
192		if idx := strings.LastIndex(name, marker); idx >= 0 {
193			name = name[idx+len(marker):]
194		}
195		if name == "" || name == "Local" {
196			return ""
197		}
198		if _, err := time.LoadLocation(name); err != nil {
199			return ""
200		}
201		return name
202	}
