204	func groupCommitsByDay(commits []userCommit) []commitDay {
205		byDate := make(map[string][]userCommit)
206		var dateOrder []string
207	
208		for _, c := range commits {
209			date := dateUnknown
210			if c.CommitDate != nil {
211				if t, err := parseFlexibleTime(*c.CommitDate); err == nil {
212					date = t.Local().Format("2006-01-02")
213				}
214			}
215			if _, exists := byDate[date]; !exists {
216				dateOrder = append(dateOrder, date)
217			}
218			byDate[date] = append(byDate[date], c)
219		}
220	
221		// Sort dates newest first, with unknown dates pushed to the end
222		sort.Slice(dateOrder, func(i, j int) bool {
223			if dateOrder[i] == dateUnknown {
224				return false
225			}
226			if dateOrder[j] == dateUnknown {
227				return true
228			}
229			return dateOrder[i] > dateOrder[j]
230		})
231	
232		result := make([]commitDay, 0, len(dateOrder))
233		for _, d := range dateOrder {
234			result = append(result, commitDay{Date: d, Commits: byDate[d]})
235		}
236		return result
237	}
