239	func normalizeAgentString(s string) string {
240		if s == "" {
241			return agentUnknown
242		}
243	
244		var sb strings.Builder
245		for _, r := range s {
246			if r == ' ' || r == '-' || r == '_' {
247				continue
248			}
249			if r >= 'A' && r <= 'Z' {
250				sb.WriteByte(byte(r + 32))
251			} else {
252				sb.WriteRune(r)
253			}
254		}
255		lower := sb.String()
256	
257		if id, ok := knownAgents[lower]; ok {
258			return id
259		}
260	
261		for _, suffix := range []string{"code", "cli"} {
262			if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
263				if id, ok := knownAgents[lower[:len(lower)-len(suffix)]]; ok {
264					return id
265				}
266			}
267		}
268	
269		if strings.HasPrefix(lower, "factoryaidroid") {
270			return "droid"
271		}
272	
273		return agentUnknown
274	}
