276	// parseFlexibleTime tries RFC3339, then RFC3339Nano.
277	func parseFlexibleTime(s string) (time.Time, error) {
278		t, err := time.Parse(time.RFC3339, s)
279		if err != nil {
280			t, err = time.Parse(time.RFC3339Nano, s)
281			if err != nil {
282				return time.Time{}, fmt.Errorf("parse time %q: %w", s, err)
283			}
284		}
285		return t, nil
286	}
